            aWandererI = aWandererI + ((((RotL64(aScatter, 35U) + RotL64(aOrbiterJ, 18U)) + aOrbiterI) + RotL64(aCarry, 47U)) + aNonceWordP);
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 19U) + aOrbiterA) + RotL64(aOrbiterK, 21U));
            aWandererA = aWandererA + (((RotL64(aCross, 38U) + aOrbiterJ) + RotL64(aOrbiterA, 11U)) + aNonceWordI);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 51U) + RotL64(aOrbiterJ, 27U)) + aOrbiterF);
