            aOrbiterB = RotL64((aOrbiterB * 0x8A12F2D0F1FD0D45ULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x7DD992EC4837F31FULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterG) ^ 0x751CD9B9EC25FB3AULL) ^ aPhaseAOrbiterUpdateSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x4956AD4E6D9EE9C1ULL), 51U);
