            //
            aOrbiterK = (aWandererH + RotL64(aCross, 43U)) + 0xA2D3CEA9B8C32C05ULL;
            aOrbiterI = ((aWandererD + RotL64(aPrevious, 4U)) + RotL64(aCarry, 53U)) + 0x6CCC8264A09A5016ULL;
            aOrbiterD = ((aWandererF + RotL64(aScatter, 51U)) + 0x6105710B62D4F4C6ULL) + aPhaseCOrbiterAssignSaltA[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterC = ((aWandererC + RotL64(aIngress, 57U)) + 0xA7ED1C92391FA8B4ULL) + aPhaseCOrbiterAssignSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterA = (aWandererJ + RotL64(aPrevious, 35U)) + 0xAC3C8A3A40EC2ADBULL;
            aOrbiterE = ((aWandererK + RotL64(aIngress, 11U)) + RotL64(aCarry, 3U)) + 0x12BF21F13F6475EBULL;
            aOrbiterH = ((aWandererG + RotL64(aCross, 19U)) + RotL64(aCarry, 27U)) + 0x716030BBCB2BEA14ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x704810AD61696760ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x64EA6AB82D6C0E37ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xD574B83C4755F5D5ULL), 13U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0xA355CB2C2DA57A26ULL) + aPhaseCOrbiterUpdateSaltA[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0xA5B5930EF6D40543ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xDCA1685962E6CC89ULL), 27U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x9E0602125DC541EEULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x6C59D135792EDC2DULL;
            aOrbiterC = RotL64((aOrbiterC * 0xC384CAFCCEB02D33ULL), 41U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x64F811BDE2AE6B3EULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x4F7AB9E1C7C86EBFULL) ^ aPhaseCOrbiterUpdateSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xCA6223396CFDDC75ULL), 21U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0x1AFB39ED7935684DULL) + aPhaseCOrbiterUpdateSaltF[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x485656E7C5E145EDULL;
            aOrbiterK = RotL64((aOrbiterK * 0x5AE0E14F446657F5ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0xD5225795150240A3ULL;
