            aWandererD = aWandererD ^ ((RotL64(aScatter, 13U) + aOrbiterE) + RotL64(aOrbiterD, 58U));
            aWandererH = aWandererH + ((RotL64(aIngress, 35U) + aOrbiterC) + RotL64(aOrbiterI, 11U));
