            aWandererG = aWandererG + (((RotL64(aIngress, 6U) + aOrbiterE) + RotL64(aOrbiterH, 21U)) + RotL64(aCarry, 37U));
            aWandererF = aWandererF ^ (((RotL64(aCross, 53U) + RotL64(aOrbiterD, 37U)) + aOrbiterH) + aPhaseCWandererUpdateSaltE[(((31U - aIndex) + 18U)) & S_SALT1]);
